import assert from 'node:assert/strict';
import { describe, test } from 'node:test';
import { CreateEventBody } from '../../dist/api/catalog/schemas/events.js';
import type { NewEvent } from '../../dist/core/catalog/types/event.js';
import { aNewEvent } from './fixtures/catalog.ts';

// FR-010
describe('CreateEventBody', () => {
  const requiredFields = ['title', 'description', 'categoryId', 'venueId', 'startsAt', 'endsAt'] as const;

  for (const field of requiredFields) {
    test(`rejects a body without ${field} and points at ${field}`, () => {
      const body: Partial<NewEvent> = aNewEvent();
      delete body[field];

      const result = CreateEventBody.safeParse(body);

      if (result.success) assert.fail('expected the body to be rejected');
      assert.deepEqual(
        result.error.issues.map((issue: { path: PropertyKey[] }) => issue.path),
        [[field]],
      );
    });
  }

  test('accepts a body with every field filled in', () => {
    const body = aNewEvent();

    const result = CreateEventBody.safeParse(body);

    assert.equal(result.success, true);
    assert.deepEqual(result.data, body);
  });
});
